// Merge trigger input with env defaults — allows both scheduled and webhook-triggered runs
const trigger = $input.first();
const body = trigger.json.body || trigger.json || {};

const config = {
  channel_name:            body.channel_name            || $env.CHANNEL_NAME            || 'My YouTube Channel',
  channel_niche:           body.channel_niche           || $env.CHANNEL_NICHE           || 'general',
  channel_url:             body.channel_url             || $env.CHANNEL_URL             || '',
  language:                body.language                || $env.CHANNEL_LANGUAGE        || 'English',
  visual_style:            body.visual_style            || $env.CHANNEL_VISUAL_STYLE    || 'cinematic, high quality, 16:9',
  target_duration_minutes: body.target_duration_minutes || parseInt($env.TARGET_DURATION_MINUTES || '15'),
  scene_seconds:           body.scene_seconds           || parseInt($env.SCENE_VIDEO_SECONDS || '8'),
  publish_mode:            body.publish_mode            || $env.PIPELINE_MODE           || 'draft',
  workspace:               '/data/pipeline',
  episode_id:              body.episode_id              || `ep_${new Date().getTime()}`
};

return [{ json: config }];

const items = $input.all();
const base = $('Code - Merge Config').first().json;
const topics = items.map(i => i.json.topic_title).filter(Boolean);
return [{ json: { ...base, previous_topics: topics.length ? topics.join(', ') : 'None' } }];

// Real YouTube channel analysis via YouTube Data API v3.
// Skips silently if no channel_url or YOUTUBE_DATA_API_KEY — GPT then operates on niche-only mode.
const cfg = $input.first().json;
const url = cfg.channel_url || '';
const apiKey = $env.YOUTUBE_DATA_API_KEY || '';

if (!url || !apiKey) {
  return [{ json: { ...cfg, channel_analysis: null } }];
}

const handleMatch  = url.match(/@([^/?#]+)/);
const channelMatch = url.match(/channel\/([^/?#]+)/);
const userMatch    = url.match(/user\/([^/?#]+)/);
let identifier = null, identifierType = null;
if (channelMatch) { identifier = channelMatch[1]; identifierType = 'channelId'; }
else if (handleMatch) { identifier = handleMatch[1]; identifierType = 'handle'; }
else if (userMatch)  { identifier = userMatch[1];  identifierType = 'username'; }

if (!identifier) {
  return [{ json: { ...cfg, channel_analysis: { error: 'Cannot parse channel URL: ' + url } } }];
}

async function fetchJson(u) {
  const r = await fetch(u);
  if (!r.ok) throw new Error(`YouTube API ${r.status}: ${(await r.text()).slice(0,200)}`);
  return r.json();
}

try {
  // 1. Resolve channel ID
  let channelId = identifierType === 'channelId' ? identifier : null;
  if (!channelId) {
    const search = await fetchJson(`https://www.googleapis.com/youtube/v3/search?part=snippet&type=channel&q=${encodeURIComponent(identifier)}&maxResults=1&key=${apiKey}`);
    channelId = search.items?.[0]?.id?.channelId;
  }
  if (!channelId) {
    return [{ json: { ...cfg, channel_analysis: { error: 'Could not resolve channel ID for ' + identifier } } }];
  }

  // 2. Channel snippet + statistics
  const ch = await fetchJson(`https://www.googleapis.com/youtube/v3/channels?part=snippet,statistics&id=${channelId}&key=${apiKey}`);
  const chInfo = ch.items?.[0];

  // 3. Top 10 videos by view count
  const top = await fetchJson(`https://www.googleapis.com/youtube/v3/search?part=snippet&channelId=${channelId}&order=viewCount&maxResults=10&type=video&key=${apiKey}`);
  const videoIds = (top.items || []).map(i => i.id?.videoId).filter(Boolean);

  let topVideos = [];
  if (videoIds.length) {
    const stats = await fetchJson(`https://www.googleapis.com/youtube/v3/videos?part=snippet,statistics,contentDetails&id=${videoIds.join(',')}&key=${apiKey}`);
    topVideos = (stats.items || []).map(v => ({
      title:        v.snippet?.title,
      description:  (v.snippet?.description || '').slice(0, 300),
      tags:         (v.snippet?.tags || []).slice(0, 10),
      published_at: v.snippet?.publishedAt,
      duration:     v.contentDetails?.duration,
      views:        parseInt(v.statistics?.viewCount || '0'),
      likes:        parseInt(v.statistics?.likeCount || '0'),
      comments:     parseInt(v.statistics?.commentCount || '0')
    })).sort((a, b) => b.views - a.views);
  }

  const analysis = {
    channel_id:        channelId,
    channel_title:     chInfo?.snippet?.title,
    channel_description: (chInfo?.snippet?.description || '').slice(0, 800),
    country:           chInfo?.snippet?.country || null,
    subscriber_count:  parseInt(chInfo?.statistics?.subscriberCount || '0'),
    total_videos:      parseInt(chInfo?.statistics?.videoCount || '0'),
    total_views:       parseInt(chInfo?.statistics?.viewCount || '0'),
    top_videos:        topVideos
  };

  return [{ json: { ...cfg, channel_analysis: analysis } }];
} catch (e) {
  return [{ json: { ...cfg, channel_analysis: { error: String(e.message || e) } } }];
}

const raw = $input.first().json.output_text || $input.first().json.text || JSON.stringify($input.first().json);
let obj;
try { obj = JSON.parse(raw); } catch(e) { obj = $input.first().json; }
return [{ json: { ...$('Code - Aggregate Topics').first().json, topic: obj } }];

