const raw = $input.first().json;
// Claude API returns content array
let refinedText = '';
if (raw.content && raw.content[0] && raw.content[0].text) {
  refinedText = raw.content[0].text;
} else if (raw.output_text) {
  refinedText = raw.output_text;
}
let refined;
try { refined = JSON.parse(refinedText); } catch(e) { refined = { narration_script: refinedText }; }

const base = $('Code - Parse Rough Script').first().json;
const finalScript = {
  ...base.script,
  narration_script: refined.narration_script || base.script.narration_script,
  title: refined.title || base.script.title,
  claude_improvements: refined.improvements_made || []
};
return [{ json: { ...base, script: finalScript } }];

const raw = $input.first().json.output_text || '{}';
let qa; try { qa = JSON.parse(raw); } catch(e) { qa = {}; }
const minScore = parseInt($env.MIN_QA_SCORE || '75');
if ((qa.score_0_100 || 0) < minScore) {
  throw new Error(`Script QA score ${qa.score_0_100} < ${minScore}. Issues: ${JSON.stringify(qa.issues)}`);
}
return [{ json: { ...$('Code - Parse Claude Refinement').first().json, qa } }];

